  1→package command
  2→
  3→import (
  4→	"errors"
  5→
  6→	"github.com/finalappstore/stupidsamba/internal/smb/dialect"
  7→	"github.com/finalappstore/stupidsamba/internal/smb/status"
  8→	"github.com/finalappstore/stupidsamba/internal/smb/wire"
  9→)
 10→
 11→func init() {
 12→	// IOCTL 不要求树连接：FSCTL_VALIDATE_NEGOTIATE_INFO 与
 13→	// FSCTL_DFS_GET_REFERRALS 都可能在没有有效 TreeId 时到达。
 14→	register(wire.CommandIoctl, true, false, handleIoctl)
 15→}
 16→
 17→// handleIoctl 处理 SMB2 IOCTL（MS-SMB2 §3.3.5.15）。
 18→//
 19→// 认不出的控制码一律回 STATUS_INVALID_DEVICE_REQUEST —— 这是 Windows 的行为，
 20→// 客户端会据此优雅退化。回 NOT_SUPPORTED 有些客户端会重试到超时。
 21→func handleIoctl(ctx *Context) error {
 22→	req, err := wire.ParseIoctlRequest(ctx.Msg)
 23→	if err != nil {
 24→		return status.InvalidParameter
 25→	}
 26→	if !req.IsFSCTL() {
 27→		// 我们不提供任何设备 IOCTL，只提供文件系统控制码。
 28→		return status.InvalidDeviceRequest
 29→	}
 30→
 31→	switch req.CtlCode {
 32→	case wire.FSCTLValidateNegotiateInfo:
 33→		return ioctlValidateNegotiate(ctx, req)
 34→	case wire.FSCTLPipeTransceive:
 35→		return ioctlPipeTransceive(ctx, req)
 36→	case wire.FSCTLQueryNetworkInterface:
 37→		// 不宣告多通道（我们不支持 SMB3 multichannel），
 38→		// 回空表示「没有额外接口」比回错误更让客户端满意。
 39→		return ioctlEmptyOK(ctx, req)
 40→	default:
 41→		ctx.Log.Debug("未实现的 FSCTL", "ctl", req.CtlCode)
 42→		return status.InvalidDeviceRequest
 43→	}
 44→}
 45→
 46→// ioctlValidateNegotiate 处理 FSCTL_VALIDATE_NEGOTIATE_INFO（MS-SMB2 §3.3.5.15.12）。
 47→//
 48→// ⚠️ 这是防降级攻击的复核：客户端把它**当初发出的** NEGOTIATE 请求内容
 49→// 再发一遍，要求服务端回显自己**当初响应过的**方言/能力/GUID/安全模式。
 50→// 任何字段对不上，Windows 会立刻 TCP RESET，且不给任何提示。
 51→func ioctlValidateNegotiate(ctx *Context, req *wire.IoctlRequest) error {
 52→	c := ctx.Conn
 53→
 54→	// MS-SMB2 §3.3.5.15.12：3.1.1 用 preauth integrity hash 覆盖了降级攻击
 55→	// 的威胁模型，客户端**不得**发这个 IOCTL；收到即视为对端行为异常，必须
 56→	// 回 STATUS_FILE_CLOSED（Windows 会直接 TCP RESET）。
 57→	if c.Dialect == dialect.SMB311 {
 58→		return status.FileClosed
 59→	}
 60→	// 连接尚未完成协商：没有可复核的基准，直接拒绝。
 61→	if c.Dialect == 0 {
 62→		return status.FileClosed
 63→	}
 64→
 65→	// 2.0.2 / 2.1 / 3.0 / 3.0.2 一律正常复核并回显。
 66→	//
 67→	// 规范建议对 < 3.0 的方言也回 STATUS_FILE_CLOSED，但实测 smbclient 4.22
 68→	// 会在 SMB 2.1 上发 FSCTL_VALIDATE_NEGOTIATE_INFO，收到 FILE_CLOSED 就
 69→	// 放弃整条连接（表现为 "tree connect failed: NT_STATUS_..."）。
 70→	// 据 AGENTS.md §9「真实客户端行为优先于规范」，这里按客户端期望处理，
 71→	// 否则 §2 要求的 SMB 2.0.2 / 2.1 文件共享对 smbclient 不可用。
 72→	in, err := wire.ParseValidateNegotiateInfoRequest(req.Input)
 73→	if err != nil {
 74→		// 输入畸形也按「校验失败」处理：断连比放行降级攻击安全。
 75→		ctx.Log.Warn("VALIDATE_NEGOTIATE_INFO 输入畸形", "err", err)
 76→		return status.AccessDenied
 77→	}
 78→
 79→	// 复核客户端重放的内容与它当初 NEGOTIATE 时说的一致。
 80→	// 不一致说明中间有人改过报文（MS-SMB2 §3.3.5.15.12）。
 81→	if in.ClientGUID != c.ClientGUID ||
 82→		in.SecurityMode != c.ClientSecurityMode ||
 83→		in.Capabilities != c.ClientCapabilities ||
 84→		!sameDialects(in.Dialects, c.ClientDialects) {
 85→		ctx.Log.Warn("VALIDATE_NEGOTIATE_INFO 校验失败，疑似降级攻击",
 86→			"remote", c.RemoteAddr)
 87→		return status.AccessDenied
 88→	}
 89→
 90→	resp := &wire.ValidateNegotiateInfoResponse{
 91→		Capabilities: c.ServerCapabilities,
 92→		ServerGUID:   c.Settings.ServerGUID,
 93→		SecurityMode: c.ServerSecurityMode,
 94→		Dialect:      wire.Dialect(c.Dialect),
 95→	}
 96→	return appendIoctlResponse(ctx, req, resp.Encode())
 97→}
 98→
 99→// ioctlPipeTransceive 处理 FSCTL_PIPE_TRANSCEIVE（MS-SMB2 §3.3.5.15.10）：
100→// 在一次往返里完成命名管道的写+读。这是现代客户端做 DCERPC 调用的默认方式。
101→func ioctlPipeTransceive(ctx *Context, req *wire.IoctlRequest) error {
102→	open, err := ctx.resolveOpen(req.FileID)
103→	if err != nil {
104→		return err
105→	}
106→	if !open.IsPipe() {
107→		return status.InvalidDeviceRequest
108→	}
109→	if len(req.Input) == 0 {
110→		return status.InvalidParameter
111→	}
112→
113→	maxOut := int(req.MaxOutputResponse)
114→	if maxOut <= 0 {
115→		return status.InvalidParameter
116→	}
117→	// 上限同时受协商出的 MaxTransactSize 约束（AGENTS.md §8 资源上限）。
118→	if maxOut > int(ctx.Conn.MaxTransactSize) {
119→		maxOut = int(ctx.Conn.MaxTransactSize)
120→	}
121→
122→	terr := open.PipeTransact(req.Input, maxOut)
123→	if terr != nil && !errors.Is(terr, ErrPipeMoreData) {
124→		ctx.Log.Warn("命名管道 transceive 失败", "pipe", open.Path, "err", terr)
125→		return status.FromVFSError(terr)
126→	}
127→
128→	data := open.PipeRead(maxOut)
129→	if err := appendIoctlResponse(ctx, req, data); err != nil {
130→		return err
131→	}
132→	if open.PipePending() > 0 {
133→		// 响应没吐完：BUFFER_OVERFLOW 通知客户端继续 READ。
134→		ctx.Status = status.BufferOverflow
135→	}
136→	return nil
137→}
138→
139→// ioctlEmptyOK 回一个成功但输出为空的 IOCTL 响应。
140→func ioctlEmptyOK(ctx *Context, req *wire.IoctlRequest) error {
141→	return appendIoctlResponse(ctx, req, nil)
142→}
143→
144→// appendIoctlResponse 组装并追加 IOCTL Response。
145→func appendIoctlResponse(ctx *Context, req *wire.IoctlRequest, output []byte) error {
146→	if uint32(len(output)) > req.MaxOutputResponse {
147→		return status.BufferTooSmall
148→	}
149→	resp := &wire.IoctlResponse{
150→		CtlCode: req.CtlCode,
151→		FileID:  req.FileID,
152→		Flags:   req.Flags,
153→		Output:  output,
154→	}
155→	out, err := resp.Append(ctx.Out)
156→	if err != nil {
157→		ctx.Log.Error("编码 IOCTL Response 失败", "ctl", req.CtlCode, "err", err)
158→		return status.InsuffServerResources
159→	}
160→	ctx.Out = out
161→	return nil
162→}
163→
164→// sameDialects 比较两个方言列表是否完全一致（顺序敏感）。
165→//
166→// 顺序敏感是有意的：VALIDATE_NEGOTIATE_INFO 的意义就是逐字节复核客户端
167→// 当初发过的内容，放松成集合比较会给攻击者留下重排的空间。
168→func sameDialects(a []wire.Dialect, b []dialect.Dialect) bool {
169→	if len(a) != len(b) {
170→		return false
171→	}
172→	for i := range a {
173→		if uint16(a[i]) != uint16(b[i]) {
174→			return false
175→		}
176→	}
177→	return true
178→}
179→

