 70→			// 同一句柄的锁互不冲突（简化：不做同句柄重叠排他锁的自冲突判定，
 71→			// 真实客户端不会这么用，Samba 也放行）。
 72→			continue
 73→		}
 74→		if !l.exclusive && !exclusive {
 75→			// 共享锁之间可以共存。
 76→			continue
 77→		}
 78→		if l.overlaps(offset, length) {
 79→			return true
 80→		}
 81→	}
 82→	return false
 83→}
 84→
 85→// add 无条件登记一条锁。调用方必须已持有 t.mu 并先做过冲突判定。
 86→func (t *lockTable) add(path string, l byteRangeLock) {
 87→	if t.byPath == nil {
 88→		t.byPath = make(map[string][]byteRangeLock)
 89→	}
 90→	t.byPath[path] = append(t.byPath[path], l)
 91→}
 92→
 93→// remove 摘除 owner 在 path 上**完全匹配** [offset, length) 的一条锁。
 94→//
 95→// MS-SMB2 §3.3.5.14.2：解锁必须与加锁的范围精确一致，
 96→// 部分解锁 / 跨锁解锁一律 STATUS_RANGE_NOT_LOCKED。
 97→// 调用方必须已持有 t.mu。
 98→func (t *lockTable) remove(path string, owner *Open, offset, length uint64) bool {
 99→	locks := t.byPath[path]
100→	for i, l := range locks {
101→		if l.owner != owner || l.offset != offset || l.length != length {
102→			continue
103→		}
104→		locks = append(locks[:i], locks[i+1:]...)
105→		if len(locks) == 0 {
106→			delete(t.byPath, path)
107→		} else {
108→			t.byPath[path] = locks
109→		}
110→		return true
111→	}
112→	return false
113→}
114→
115→// releaseAll 释放某个句柄持有的全部锁。
116→//
117→// CLOSE、LOGOFF、TREE_DISCONNECT、连接断开都要走到这里，
118→// 否则一个崩掉的客户端会把文件永久锁死（MS-SMB2 §3.3.5.10）。
119→func (t *lockTable) releaseAll(owner *Open) {
120→	if t == nil {
121→		return
122→	}
123→	t.mu.Lock()
124→	defer t.mu.Unlock()
125→
126→	for path, locks := range t.byPath {
127→		kept := locks[:0]
128→		for _, l := range locks {
129→			if l.owner != owner {
130→				kept = append(kept, l)
131→			}
132→		}
133→		if len(kept) == 0 {
134→			delete(t.byPath, path)
135→		} else {
136→			t.byPath[path] = kept
137→		}
138→	}
139→}
140→
141→// count 返回某个句柄当前持有的锁数量，用于测试。
142→func (t *lockTable) count(owner *Open) int {
143→	t.mu.Lock()
144→	defer t.mu.Unlock()
145→
146→	n := 0
147→	for _, locks := range t.byPath {
148→		for _, l := range locks {
149→			if l.owner == owner {
150→				n++
151→			}
152→		}
153→	}
154→	return n
155→}
156→
157→// handleLock 处理 SMB2 LOCK（MS-SMB2 §3.3.5.14）。
158→//
159→// 支持的语义：
160→//   - 加锁（共享/排他）：与**其它句柄**的锁做重叠冲突判定，无冲突即授予；
161→//   - 解锁：必须与加锁范围精确一致；
162→//   - 数组内要么全是加锁、要么全是解锁，混用回 STATUS_INVALID_PARAMETER；
163→//   - 数组内任意一条失败，本请求中**已经授予的部分必须回滚**（原子性）。
164→//
165→// 未实现：阻塞等待。SMB2_LOCKFLAG_FAIL_IMMEDIATELY 未置位时规范要求服务端
166→// 挂起该请求（回 STATUS_PENDING，等锁释放或收到 CANCEL 再了结）。本服务端
167→// 目前所有 handler 都是同步执行的，没有异步未决请求表，因此一律按"立即失败"
168→// 处理并回 STATUS_LOCK_NOT_GRANTED。
169→// TODO: 等异步未决请求表（见 cancel.go）做好后改为真正的阻塞等待。
170→func handleLock(ctx *Context) error {
171→	req, err := wire.ParseLockRequest(ctx.Msg)
172→	if err != nil {
173→		return status.InvalidParameter
174→	}
175→
176→	open, err := ctx.resolveOpen(req.FileID)
177→	if err != nil {
178→		return err
179→	}
180→	// 目录上不能加字节范围锁（MS-SMB2 §3.3.5.14）。
181→	if open.IsDir {
182→		return status.InvalidParameter
183→	}
184→	if open.IsPipe() {
185→		// 管道没有字节范围的概念。
186→		return status.InvalidDeviceRequest
187→	}
188→
189→	// §3.3.5.14："If the flags of the first element ... SMB2_LOCKFLAG_UNLOCK,
190→	// and any other element does not have it set, the server MUST fail the
191→	// request with STATUS_INVALID_PARAMETER."（反之亦然）
192→	unlockMode := req.Locks[0].Flags.IsUnlock()
193→	for _, e := range req.Locks {
194→		if e.Flags.IsUnlock() != unlockMode {
195→			return status.InvalidParameter
196→		}
197→		if err := validateLockFlags(e.Flags); err != nil {
198→			return err
199→		}
200→	}
201→
202→	table := ctx.Tree.Share.lockTable()
203→	table.mu.Lock()
204→	defer table.mu.Unlock()
205→
206→	path := open.Path
207→
208→	if unlockMode {
209→		for i, e := range req.Locks {
210→			if !table.remove(path, open, e.Offset, e.Length) {
211→				// 回滚：把本请求中已经解掉的锁装回去。
212→				for _, done := range req.Locks[:i] {
213→					table.add(path, byteRangeLock{
214→						owner:     open,
215→						offset:    done.Offset,
216→						length:    done.Length,
217→						exclusive: done.Flags.IsExclusive(),
218→					})
219→				}
220→				return status.RangeNotLocked
221→			}
222→		}
223→		ctx.Out = (&wire.LockResponse{}).Append(ctx.Out)
224→		return nil
225→	}
226→
227→	for i, e := range req.Locks {
228→		exclusive := e.Flags.IsExclusive()
229→		if table.conflict(path, open, e.Offset, e.Length, exclusive) {
230→			// 回滚本请求中已经授予的锁。
231→			for _, done := range req.Locks[:i] {
232→				table.remove(path, open, done.Offset, done.Length)
233→			}
234→			if !e.Flags.FailImmediately() {
235→				ctx.Log.Debug("阻塞式 LOCK 暂按立即失败处理（未实现异步等待）",
236→					"path", path, "offset", e.Offset, "length", e.Length)
237→			}
238→			return status.LockNotGranted
239→		}
240→		table.add(path, byteRangeLock{
241→			owner:     open,
242→			offset:    e.Offset,
243→			length:    e.Length,
244→			exclusive: exclusive,
245→		})
246→	}
247→
248→	ctx.Out = (&wire.LockResponse{}).Append(ctx.Out)
249→	return nil
250→}
251→
252→// validateLockFlags 校验单个 SMB2_LOCK_ELEMENT 的 Flags 组合
253→// （MS-SMB2 §2.2.26.1 / §3.3.5.14）。
254→func validateLockFlags(f wire.LockFlags) error {
255→	if f.IsUnlock() {
256→		// UNLOCK 不能与 SHARED / EXCLUSIVE / FAIL_IMMEDIATELY 同时出现。
257→		if f&(wire.LockFlagSharedLock|wire.LockFlagExclusiveLock|
258→			wire.LockFlagFailImmediately) != 0 {
259→			return status.InvalidParameter
260→		}
261→		return nil
262→	}
263→	shared := f&wire.LockFlagSharedLock != 0
264→	excl := f&wire.LockFlagExclusiveLock != 0
265→	if shared == excl {
266→		// 既没指定也不能两个都指定。
267→		return status.InvalidParameter
268→	}
269→	return nil
270→}
