 46→// TestLockSharedCoexistExclusiveDoesNot：共享锁之间可以重叠共存，
 47→// 独占锁与任何重叠锁互斥。
 48→func TestLockSharedCoexistExclusiveDoesNot(t *testing.T) {
 49→	var tbl lockTable
