 78→func TestLockAllOrNothing(t *testing.T) {
 79→	var tbl lockTable
 80→	a, b := &Open{}, &Open{}
 81→
 82→	if st := tbl.lock("f", a, []wire.LockElement{el(200, 50, true)}); st != status.Success {
 83→		t.Fatalf("A 加锁应成功，实际 %v", st)
