 29→	a, b := &Open{}, &Open{}
 30→
 31→	if st := tbl.lock("f", a, []wire.LockElement{el(0, 100, true)}); st != status.Success {
 32→		t.Fatalf("A 首次加独占锁应成功，实际 %v", st)
 33→	}
 34→	if st := tbl.lock("f", b, []wire.LockElement{el(50, 100, true)}); st != status.LockNotGranted {
 35→		t.Fatalf("B 锁重叠区间应回 STATUS_LOCK_NOT_GRANTED，实际 %v", st)
 36→	}
 37→	if st := tbl.lock("f", b, []wire.LockElement{el(100, 100, true)}); st != status.Success {
 38→		t.Fatalf("B 锁 [100,200) 与 [0,100) 不相交，应成功，实际 %v", st)
 39→	}
 40→	// 不同文件互不影响。
 41→	if st := tbl.lock("g", b, []wire.LockElement{el(0, 100, true)}); st != status.Success {
 42→		t.Fatalf("另一个文件上的同区间应成功，实际 %v", st)
 43→	}
 44→}
