 76→// TestLockAllOrNothing：一条请求里任何一条元素冲突，整条请求都不得留下
 77→// 部分已授予的锁（MS-SMB2 §3.3.5.14）。
 78→func TestLockAllOrNothing(t *testing.T) {
 79→	var tbl lockTable
 80→	a, b := &Open{}, &Open{}
 81→
 82→	if st := tbl.lock("f", a, []wire.LockElement{el(200, 50, true)}); st != status.Success {
 83→		t.Fatalf("A 加锁应成功，实际 %v", st)
 84→	}
 85→	// B 请求两条：第一条本可授予，第二条与 A 冲突 → 整条失败。
 86→	st := tbl.lock("f", b, []wire.LockElement{el(0, 50, true), el(200, 50, true)})
 87→	if st != status.LockNotGranted {
 88→		t.Fatalf("含冲突的批量加锁应整体失败，实际 %v", st)
 89→	}
 90→	// 关键断言：第一条不能被留下。用另一个句柄去锁 [0,50) 验证它是空闲的。
 91→	c := &Open{}
 92→	if st := tbl.lock("f", c, []wire.LockElement{el(0, 50, true)}); st != status.Success {
 93→		t.Fatalf("失败的批量请求不应留下部分锁，[0,50) 应仍空闲，实际 %v", st)
