 97→// TestUnlockRequiresExactRange：解锁区间必须与加锁时完全一致，
 98→// 否则 STATUS_RANGE_NOT_LOCKED。
 99→func TestUnlockRequiresExactRange(t *testing.T) {
100→	var tbl lockTable
101→	a := &Open{}
102→
103→	if st := tbl.lock("f", a, []wire.LockElement{el(0, 100, true)}); st != status.Success {
104→		t.Fatalf("加锁应成功，实际 %v", st)
105→	}
106→	if st := tbl.unlock("f", a, []wire.LockElement{unlockEl(0, 50)}); st != status.RangeNotLocked {
107→		t.Fatalf("部分区间解锁应回 STATUS_RANGE_NOT_LOCKED，实际 %v", st)
108→	}
109→	// 别人的锁也解不掉。
110→	b := &Open{}
111→	if st := tbl.unlock("f", b, []wire.LockElement{unlockEl(0, 100)}); st != status.RangeNotLocked {
112→		t.Fatalf("解别人的锁应回 STATUS_RANGE_NOT_LOCKED，实际 %v", st)
113→	}
114→	if st := tbl.unlock("f", a, []wire.LockElement{unlockEl(0, 100)}); st != status.Success {
115→		t.Fatalf("精确解锁应成功，实际 %v", st)
116→	}
117→	// 解锁后别人就能锁了。
118→	if st := tbl.lock("f", b, []wire.LockElement{el(0, 100, true)}); st != status.Success {
119→		t.Fatalf("解锁后 B 应能加锁，实际 %v", st)
120→	}
121→}
