  1→package command
  2→
  3→import (
  4→	"errors"
  5→	"math"
  6→
  7→	"github.com/finalappstore/stupidsamba/internal/smb/dialect"
  8→	"github.com/finalappstore/stupidsamba/internal/smb/status"
  9→	"github.com/finalappstore/stupidsamba/internal/smb/wire"
 10→	"github.com/finalappstore/stupidsamba/internal/vfs"
 11→)
 12→
 13→func init() {
 14→	// IOCTL 不要求树连接：FSCTL_VALIDATE_NEGOTIATE_INFO 与
 15→	// FSCTL_DFS_GET_REFERRALS 都可能在没有有效 TreeId 时到达。
 16→	register(wire.CommandIoctl, true, false, handleIoctl)
 17→}
 18→
 19→// handleIoctl 处理 SMB2 IOCTL（MS-SMB2 §3.3.5.15）。
 20→//
 21→// 认不出的控制码一律回 STATUS_INVALID_DEVICE_REQUEST —— 这是 Windows 的行为，
 22→// 客户端会据此优雅退化。回 NOT_SUPPORTED 有些客户端会重试到超时。
 23→func handleIoctl(ctx *Context) error {
 24→	req, err := wire.ParseIoctlRequest(ctx.Msg)
 25→	if err != nil {
 26→		return status.InvalidParameter
 27→	}
 28→	if !req.IsFSCTL() {
 29→		// 我们不提供任何设备 IOCTL，只提供文件系统控制码。
 30→		return status.InvalidDeviceRequest
 31→	}
 32→
 33→	switch req.CtlCode {
 34→	case wire.FSCTLValidateNegotiateInfo:
 35→		return ioctlValidateNegotiate(ctx, req)
 36→	case wire.FSCTLPipeTransceive:
 37→		return ioctlPipeTransceive(ctx, req)
 38→	case wire.FSCTLQueryNetworkInterface:
 39→		// 不宣告多通道（我们不支持 SMB3 multichannel），
 40→		// 回空表示「没有额外接口」比回错误更让客户端满意。
 41→		return ioctlEmptyOK(ctx, req)
 42→	case wire.FSCTLSetSparse:
 43→		return ioctlSetSparse(ctx, req)
 44→	case wire.FSCTLSetZeroData:
 45→		return ioctlSetZeroData(ctx, req)
 46→	case wire.FSCTLQueryAllocatedRanges:
 47→		return ioctlQueryAllocatedRanges(ctx, req)
 48→	default:
 49→		ctx.Log.Debug("未实现的 FSCTL", "ctl", req.CtlCode)
 50→		return status.InvalidDeviceRequest
 51→	}
 52→}
 53→
 54→// ioctlValidateNegotiate 处理 FSCTL_VALIDATE_NEGOTIATE_INFO（MS-SMB2 §3.3.5.15.12）。
 55→//
 56→// ⚠️ 这是防降级攻击的复核：客户端把它**当初发出的** NEGOTIATE 请求内容
 57→// 再发一遍，要求服务端回显自己**当初响应过的**方言/能力/GUID/安全模式。
 58→// 任何字段对不上，Windows 会立刻 TCP RESET，且不给任何提示。
 59→func ioctlValidateNegotiate(ctx *Context, req *wire.IoctlRequest) error {
 60→	c := ctx.Conn
 61→
 62→	// MS-SMB2 §3.3.5.15.12：3.1.1 用 preauth integrity hash 覆盖了降级攻击
 63→	// 的威胁模型，客户端**不得**发这个 IOCTL；收到即视为对端行为异常，必须
 64→	// 回 STATUS_FILE_CLOSED（Windows 会直接 TCP RESET）。
 65→	if c.Dialect == dialect.SMB311 {
 66→		return status.FileClosed
 67→	}
 68→	// 连接尚未完成协商：没有可复核的基准，直接拒绝。
 69→	if c.Dialect == 0 {
 70→		return status.FileClosed
 71→	}
 72→
 73→	// 2.0.2 / 2.1 / 3.0 / 3.0.2 一律正常复核并回显。
 74→	//
 75→	// 规范建议对 < 3.0 的方言也回 STATUS_FILE_CLOSED，但实测 smbclient 4.22
 76→	// 会在 SMB 2.1 上发 FSCTL_VALIDATE_NEGOTIATE_INFO，收到 FILE_CLOSED 就
 77→	// 放弃整条连接（表现为 "tree connect failed: NT_STATUS_..."）。
 78→	// 据 AGENTS.md §9「真实客户端行为优先于规范」，这里按客户端期望处理，
 79→	// 否则 §2 要求的 SMB 2.0.2 / 2.1 文件共享对 smbclient 不可用。
 80→	in, err := wire.ParseValidateNegotiateInfoRequest(req.Input)
 81→	if err != nil {
 82→		// 输入畸形也按「校验失败」处理：断连比放行降级攻击安全。
 83→		ctx.Log.Warn("VALIDATE_NEGOTIATE_INFO 输入畸形", "err", err)
 84→		return status.AccessDenied
 85→	}
 86→
 87→	// 复核客户端重放的内容与它当初 NEGOTIATE 时说的一致。
 88→	// 不一致说明中间有人改过报文（MS-SMB2 §3.3.5.15.12）。
 89→	if in.ClientGUID != c.ClientGUID ||
 90→		in.SecurityMode != c.ClientSecurityMode ||
 91→		in.Capabilities != c.ClientCapabilities ||
 92→		!sameDialects(in.Dialects, c.ClientDialects) {
 93→		ctx.Log.Warn("VALIDATE_NEGOTIATE_INFO 校验失败，疑似降级攻击",
 94→			"remote", c.RemoteAddr)
 95→		return status.AccessDenied
 96→	}
 97→
 98→	resp := &wire.ValidateNegotiateInfoResponse{
 99→		Capabilities: c.ServerCapabilities,
100→		ServerGUID:   c.Settings.ServerGUID,
101→		SecurityMode: c.ServerSecurityMode,
102→		Dialect:      wire.Dialect(c.Dialect),
103→	}
104→	return appendIoctlResponse(ctx, req, resp.Encode())
105→}
106→
107→// ioctlPipeTransceive 处理 FSCTL_PIPE_TRANSCEIVE（MS-SMB2 §3.3.5.15.10）：
108→// 在一次往返里完成命名管道的写+读。这是现代客户端做 DCERPC 调用的默认方式。
109→func ioctlPipeTransceive(ctx *Context, req *wire.IoctlRequest) error {
110→	open, err := ctx.resolveOpen(req.FileID)
111→	if err != nil {
112→		return err
113→	}
114→	if !open.IsPipe() {
115→		return status.InvalidDeviceRequest
116→	}
117→	if len(req.Input) == 0 {
118→		return status.InvalidParameter
119→	}
120→
121→	maxOut := int(req.MaxOutputResponse)
122→	if maxOut <= 0 {
123→		return status.InvalidParameter
124→	}
125→	// 上限同时受协商出的 MaxTransactSize 约束（AGENTS.md §8 资源上限）。
126→	if maxOut > int(ctx.Conn.MaxTransactSize) {
127→		maxOut = int(ctx.Conn.MaxTransactSize)
128→	}
129→
130→	terr := open.PipeTransact(req.Input, maxOut)
131→	if terr != nil && !errors.Is(terr, ErrPipeMoreData) {
132→		ctx.Log.Warn("命名管道 transceive 失败", "pipe", open.Path, "err", terr)
133→		return status.FromVFSError(terr)
134→	}
135→
136→	data := open.PipeRead(maxOut)
137→	if err := appendIoctlResponse(ctx, req, data); err != nil {
138→		return err
139→	}
140→	if open.PipePending() > 0 {
141→		// 响应没吐完：BUFFER_OVERFLOW 通知客户端继续 READ。
142→		ctx.Status = status.BufferOverflow
143→	}
144→	return nil
145→}
