148→// 稀疏文件三兄弟：SET_SPARSE / SET_ZERO_DATA / QUERY_ALLOCATED_RANGES
149→//
150→// 这是 Time Machine 的关键路径（AGENTS.md §2 阶段二）：.sparsebundle 由几万个
151→// 固定大小的 band 文件组成，备份过期回收时 macOS 会把 band 里的区间打洞释放，
152→// 再用 QUERY_ALLOCATED_RANGES 核对哪些区间还占着盘。没有这三个 FSCTL，
153→// 备份卷只会越长越大、永远不会缩小。
154→//
155→// 客户端只有在 FileFsAttributeInformation 宣告了 FILE_SUPPORTS_SPARSE_FILES
156→// 时才会发它们（见 query_info.go 的 fsAttributes）。
157→// ---------------------------------------------------------------------------
158→
159→// sparseTarget 做这三个 FSCTL 共同的前置校验，返回可用的 VFS 稀疏能力。
160→//
161→// write 为 true 时额外要求共享可写与写权限。
162→func sparseTarget(ctx *Context, req *wire.IoctlRequest, write bool) (*Open, vfs.SparseFile, error) {
163→	open, err := ctx.resolveOpen(req.FileID)
164→	if err != nil {
165→		return nil, nil, err
166→	}
167→	if open.IsPipe() {
168→		return nil, nil, status.InvalidDeviceRequest
169→	}
170→	// 目录不可能是稀疏文件（MS-FSA §2.1.5.9.29 / §2.1.5.9.21）。
171→	if open.IsDir {
172→		return nil, nil, status.InvalidParameter
173→	}
174→	h := open.Handle
175→	if h == nil {
176→		return nil, nil, status.FileClosed
177→	}
178→	if write {
179→		if err := ctx.RequireWritable(); err != nil {
180→			return nil, nil, err
181→		}
182→		// MS-FSA §2.1.5.9.29：FILE_WRITE_DATA 或 FILE_WRITE_ATTRIBUTES 之一即可。
183→		if open.GrantedAccess&(wire.FileWriteData|wire.FileWriteAttributes) == 0 {
184→			return nil, nil, status.AccessDenied
185→		}
186→	}
187→
188→	sp, ok := h.(vfs.SparseFile)
189→	if !ok {
190→		// 后端没有打洞能力：明确回不支持，别假装成功。
191→		// 假装成功会让客户端以为空间已释放，容量统计从此对不上。
192→		return nil, nil, status.NotSupported
193→	}
194→	return open, sp, nil
195→}
196→
197→// ioctlSetSparse 处理 FSCTL_SET_SPARSE（MS-FSCC §2.3.69 / MS-FSA §2.1.5.9.29）。
198→//
199→// 输入是**可选的** 1 字节 FILE_SET_SPARSE_BUFFER{ SetSparse BOOLEAN }，
200→// 规范明确规定输入为空时视为 TRUE。无输出。
201→//
202→// POSIX 语义差异：Unix 上没有「稀疏标志位」这个东西 —— 只要底层文件系统支持
203→// 打洞，任何文件天生就能变稀疏，不需要事先声明。vfs 层据此把 SetSparse 实现成
204→// 无操作（见 vfs.SparseFile.SetSparse 的注释：回 ErrNotSupported 会让 macOS
205→// 在建 .sparsebundle 时直接放弃）。
206→func ioctlSetSparse(ctx *Context, req *wire.IoctlRequest) error {
207→	open, sp, err := sparseTarget(ctx, req, true)
208→	if err != nil {
209→		return err
210→	}
211→
212→	setSparse := true
213→	if len(req.Input) > 0 {
214→		setSparse = req.Input[0] != 0
215→	}
216→	if err := sp.SetSparse(setSparse); err != nil {
217→		ctx.Log.Warn("SET_SPARSE 失败", "path", open.Path, "sparse", setSparse, "err", err)
218→		return status.FromVFSError(err)
219→	}
220→	return ioctlEmptyOK(ctx, req)
221→}
222→
223→// ioctlSetZeroData 处理 FSCTL_SET_ZERO_DATA（MS-FSCC §2.3.79 / MS-FSA §2.1.5.9.40）：
224→// 把 [FileOffset, BeyondFinalZero) 置零。
225→//
226→// 规范允许两种实现：真写零，或者（稀疏文件）打洞。我们走打洞 —— 读回来同样是零，
227→// 但盘上空间真的还给了文件系统，这正是 Time Machine 回收 band 的意义所在。
228→func ioctlSetZeroData(ctx *Context, req *wire.IoctlRequest) error {
229→	open, sp, err := sparseTarget(ctx, req, true)
230→	if err != nil {
231→		return err
232→	}
233→	// 置零是写操作，WRITE_ATTRIBUTES 不够（MS-FSA §2.1.5.9.40）。
234→	if open.GrantedAccess&wire.FileWriteData == 0 {
235→		return status.AccessDenied
236→	}
237→
238→	z, perr := wire.ParseZeroDataInput(req.Input)
239→	if perr != nil {
240→		return status.InvalidParameter
241→	}
242→	if n := z.BeyondFinalZero - z.FileOffset; n > 0 {
243→		if err := sp.PunchHole(z.FileOffset, n); err != nil {
244→			ctx.Log.Warn("SET_ZERO_DATA 打洞失败", "path", open.Path, "err", err)
245→			return status.FromVFSError(err)
246→		}
247→	}
248→	return ioctlEmptyOK(ctx, req)
249→}
250→
251→// ioctlQueryAllocatedRanges 处理 FSCTL_QUERY_ALLOCATED_RANGES
252→// （MS-FSCC §2.3.20 / MS-FSA §2.1.5.9.21）。
253→//
254→// 输入是单个 FILE_ALLOCATED_RANGE_BUFFER（16 字节小端，描述要查询的区间），
255→// 输出是同结构的**数组**，列出该区间内真正占着盘的部分。
256→func ioctlQueryAllocatedRanges(ctx *Context, req *wire.IoctlRequest) error {
257→	open, sp, err := sparseTarget(ctx, req, false)
258→	if err != nil {
259→		return err
260→	}
261→	// 读区间分布至少要有读或写权限之一。macOS 的 band 文件是读写打开的。
262→	if open.GrantedAccess&(wire.FileReadData|wire.FileWriteData) == 0 {
263→		return status.AccessDenied
264→	}
265→
266→	in, perr := wire.ParseAllocatedRangesInput(req.Input)
267→	if perr != nil {
268→		return status.InvalidParameter
269→	}
270→	// 负值与相加溢出都必须挡掉（AGENTS.md §8）。
271→	if in.FileOffset < 0 || in.Length < 0 || in.FileOffset > math.MaxInt64-in.Length {
272→		return status.InvalidParameter
273→	}
274→
275→	vr, qerr := sp.AllocatedRanges(in.FileOffset, in.Length)
276→	if qerr != nil {
277→		ctx.Log.Warn("QUERY_ALLOCATED_RANGES 失败", "path", open.Path, "err", qerr)
278→		return status.FromVFSError(qerr)
279→	}
280→	ranges := make([]wire.FileAllocatedRangeBuffer, len(vr))
281→	for i, r := range vr {
282→		ranges[i] = wire.FileAllocatedRangeBuffer{FileOffset: r.Offset, Length: r.Length}
283→	}
284→
285→	// 输出装不下时截断到整数个区间并回 STATUS_BUFFER_OVERFLOW —— 这是规范
286→	// 规定的正常流程（客户端据此缩小查询区间重试），不是错误。
287→	out, overflow := truncateAllocatedRanges(ranges, req.MaxOutputResponse)
288→	if err := appendIoctlResponse(ctx, req, out); err != nil {
289→		return err
290→	}
291→	if overflow {
292→		ctx.Status = status.BufferOverflow
293→	}
294→	return nil
295→}
296→
297→// allocatedRangeSize 是 FILE_ALLOCATED_RANGE_BUFFER 的字节数
298→// （FileOffset INT64 + Length INT64，MS-FSCC §2.3.21.1）。
299→const allocatedRangeSize = 16
300→
301→// truncateAllocatedRanges 把区间数组编码进不超过 maxOut 字节的缓冲。
302→//
303→// 只能按**整个** FILE_ALLOCATED_RANGE_BUFFER 截断，切一半会让客户端解析出
304→// 一个错误的区间。返回是否发生了截断。
305→func truncateAllocatedRanges(ranges []wire.FileAllocatedRangeBuffer, maxOut uint32) ([]byte, bool) {
306→	fit := int(maxOut / allocatedRangeSize)
307→	overflow := false
308→	if fit < len(ranges) {
309→		ranges = ranges[:fit]
310→		overflow = true
311→	}
312→	if len(ranges) == 0 {
313→		// 全是空洞（或一条都装不下）：空输出是合法响应。
314→		return nil, overflow
315→	}
316→	return wire.AppendAllocatedRanges(nil, ranges), overflow
317→}
318→
319→// ioctlEmptyOK 回一个成功但输出为空的 IOCTL 响应。
320→func ioctlEmptyOK(ctx *Context, req *wire.IoctlRequest) error {
321→	return appendIoctlResponse(ctx, req, nil)
322→}
323→
324→// appendIoctlResponse 组装并追加 IOCTL Response。
325→func appendIoctlResponse(ctx *Context, req *wire.IoctlRequest, output []byte) error {
326→	if uint32(len(output)) > req.MaxOutputResponse {
327→		return status.BufferTooSmall
328→	}
329→	resp := &wire.IoctlResponse{
330→		CtlCode: req.CtlCode,
331→		FileID:  req.FileID,
332→		Flags:   req.Flags,
333→		Output:  output,
334→	}
335→	out, err := resp.Append(ctx.Out)
336→	if err != nil {
337→		ctx.Log.Error("编码 IOCTL Response 失败", "ctl", req.CtlCode, "err", err)
338→		return status.InsuffServerResources
339→	}
340→	ctx.Out = out
341→	return nil
342→}
343→
344→// sameDialects 比较两个方言列表是否完全一致（顺序敏感）。
345→//
346→// 顺序敏感是有意的：VALIDATE_NEGOTIATE_INFO 的意义就是逐字节复核客户端
347→// 当初发过的内容，放松成集合比较会给攻击者留下重排的空间。
348→func sameDialects(a []wire.Dialect, b []dialect.Dialect) bool {
349→	if len(a) != len(b) {
350→		return false
351→	}
352→	for i := range a {
353→		if uint16(a[i]) != uint16(b[i]) {
354→			return false
355→		}
356→	}
357→	return true
358→}
