 10→// grant 在 tbl 上模拟一次"冲突判定 + 登记"，返回是否授予。
 11→//
 12→// 这正是 handleLock 对每条 LockElement 做的事，抽出来让锁语义可以脱离
 13→// 完整的 Context/Session 装配单独测试。
 14→func grant(tbl *lockTable, path string, owner *Open, off, length uint64, excl bool) bool {
 15→	tbl.mu.Lock()
 16→	defer tbl.mu.Unlock()
 17→
 18→	if tbl.conflict(path, owner, off, length, excl) {
 19→		return false
 20→	}
 21→	tbl.add(path, byteRangeLock{
 22→		owner: owner, offset: off, length: length, exclusive: excl,
 23→	})
 24→	return true
 25→}
 26→
 27→// release 摘除一条精确匹配的锁，返回是否找到。
 28→func release(tbl *lockTable, path string, owner *Open, off, length uint64) bool {
 29→	tbl.mu.Lock()
 30→	defer tbl.mu.Unlock()
 31→
 32→	return tbl.remove(path, owner, off, length)
 33→}
