 35→// TestLockExclusiveBlocksOtherHandle：A 持独占锁后，B 不能锁重叠区间，
 36→// 但可以锁不相交的区间；不同文件互不影响。
 37→func TestLockExclusiveBlocksOtherHandle(t *testing.T) {
 38→	var tbl lockTable
 39→	a, b := &Open{}, &Open{}
 40→
 41→	if !grant(&tbl, "f", a, 0, 100, true) {
 42→		t.Fatal("A 首次加独占锁应成功")
 43→	}
 44→	if grant(&tbl, "f", b, 50, 100, true) {
 45→		t.Fatal("B 锁重叠区间 [50,150) 应被拒")
 46→	}
 47→	if !grant(&tbl, "f", b, 100, 100, true) {
 48→		t.Fatal("B 锁 [100,200) 与 [0,100) 不相交，应成功")
 49→	}
 50→	if !grant(&tbl, "g", b, 0, 100, true) {
 51→		t.Fatal("另一个文件上的同区间不应受影响")
 52→	}
 53→}
