 55→// TestLockSharedCoexistExclusiveDoesNot：共享锁之间可以重叠共存，
 56→// 独占锁与任何重叠锁互斥。
 57→func TestLockSharedCoexistExclusiveDoesNot(t *testing.T) {
 58→	var tbl lockTable
 59→	a, b, c := &Open{}, &Open{}, &Open{}
 60→
 61→	if !grant(&tbl, "f", a, 0, 100, false) {
 62→		t.Fatal("A 共享锁应成功")
