 72→// TestLockSameHandleNoSelfConflict：同一个句柄自己的锁不与自己冲突。
 73→func TestLockSameHandleNoSelfConflict(t *testing.T) {
 74→	var tbl lockTable
 75→	a := &Open{}
 76→
 77→	if !grant(&tbl, "f", a, 0, 100, true) {
