 87→func TestUnlockRequiresExactRange(t *testing.T) {
 88→	var tbl lockTable
 89→	a, b := &Open{}, &Open{}
 90→
 91→	if !grant(&tbl, "f", a, 0, 100, true) {
 92→		t.Fatal("加锁应成功")
 93→	}
 94→	if release(&tbl, "f", a, 0, 50) {
 95→		t.Fatal("部分区间解锁必须失败")
 96→	}
 97→	if release(&tbl, "f", b, 0, 100) {
 98→		t.Fatal("不能解别人持有的锁")
 99→	}
100→	if !release(&tbl, "f", a, 0, 100) {
101→		t.Fatal("精确解锁应成功")
102→	}
103→	if !grant(&tbl, "f", b, 0, 100, true) {
104→		t.Fatal("解锁后 B 应能加锁")
105→	}
106→}
107→
108→// TestReleaseAllOnClose：releaseAll 释放该句柄的全部锁，且不动别人的。
109→// 句柄关闭时若不释放，崩掉的客户端会把文件永久锁死。
110→func TestReleaseAllOnClose(t *testing.T) {
111→	var tbl lockTable
112→	a, b := &Open{}, &Open{}
113→
114→	if !grant(&tbl, "f", a, 0, 10, true) || !grant(&tbl, "f", a, 100, 10, true) {
115→		t.Fatal("A 加两把锁应成功")
116→	}
117→	if !grant(&tbl, "f", b, 200, 10, true) {
118→		t.Fatal("B 加锁应成功")
119→	}
120→	if n := tbl.count(a); n != 2 {
121→		t.Fatalf("A 应持有 2 把锁，实际 %d", n)
122→	}
123→
124→	tbl.releaseAll("f", a)
125→
126→	if n := tbl.count(a); n != 0 {
127→		t.Fatalf("releaseAll 后 A 应持有 0 把锁，实际 %d", n)
128→	}
129→	if n := tbl.count(b); n != 1 {
130→		t.Fatalf("B 的锁不应被 A 的 releaseAll 带走，实际 %d", n)
131→	}
132→
133→	c := &Open{}
134→	if !grant(&tbl, "f", c, 0, 10, true) || !grant(&tbl, "f", c, 100, 10, true) {
135→		t.Fatal("A 的区间应已可用")
136→	}
137→	if grant(&tbl, "f", c, 200, 10, true) {
138→		t.Fatal("B 的区间仍应被占用")
139→	}
140→}
