142→// TestLockTableEmptiesOut：锁全部释放后不留空桶，避免长跑内存泄漏。
143→func TestLockTableEmptiesOut(t *testing.T) {
144→	var tbl lockTable
145→	a := &Open{}
146→
147→	if !grant(&tbl, "f", a, 0, 10, true) {
148→		t.Fatal("加锁应成功")
149→	}
150→	tbl.releaseAll("f", a)
151→	if _, ok := tbl.byPath["f"]; ok {
152→		t.Fatal("锁全部释放后不应残留路径桶")
153→	}
154→
155→	// remove 路径也要清桶。
156→	if !grant(&tbl, "f", a, 0, 10, true) {
157→		t.Fatal("重新加锁应成功")
158→	}
159→	if !release(&tbl, "f", a, 0, 10) {
160→		t.Fatal("解锁应成功")
161→	}
162→	if _, ok := tbl.byPath["f"]; ok {
163→		t.Fatal("remove 摘掉最后一把锁后也应清掉路径桶")
164→	}
165→}
