167→// TestLockZeroLengthNeverConflicts：长度为 0 的锁不占据任何字节，
168→// 与谁都不冲突（MS-FSA §2.1.4.10）。
169→func TestLockZeroLengthNeverConflicts(t *testing.T) {
170→	var tbl lockTable
171→	a, b := &Open{}, &Open{}
172→
173→	if !grant(&tbl, "f", a, 0, 0, true) {
174→		t.Fatal("零长度加锁应成功")
175→	}
176→	if !grant(&tbl, "f", b, 0, 100, true) {
177→		t.Fatal("零长度锁不应挡住别人")
178→	}
179→	if !grant(&tbl, "f", a, 50, 0, true) {
180→		t.Fatal("在别人独占区间内加零长度锁也应成功")
181→	}
182→}
183→
184→// TestLockOverlapNoIntegerOverflow：offset+length 在 uint64 上回绕时
185→// 不能把"相交"误判成"不相交"（AGENTS.md §8 整数溢出防御）。
186→//
187→// 若实现用裸加法算区间终点，[max-10, max-10+20) 的终点会回绕成一个极小值，
188→// 冲突判定就会错误放行 —— 那等于锁在文件尾部完全失效。
189→func TestLockOverlapNoIntegerOverflow(t *testing.T) {
190→	var tbl lockTable
191→	a, b := &Open{}, &Open{}
192→
193→	const max = uint64(math.MaxUint64)
194→
195→	if !grant(&tbl, "f", a, max-10, 20, true) {
196→		t.Fatal("A 在回绕区间加锁应成功")
197→	}
198→	if grant(&tbl, "f", b, max-5, 20, true) {
199→		t.Fatal("回绕区间仍然相交，B 必须被拒")
200→	}
201→	if !grant(&tbl, "f", b, 0, 10, true) {
202→		t.Fatal("低位不相交区间应放行")
203→	}
204→
205→	// 反向顺序同样成立：先锁高位小区间，再锁跨越它的大区间。
206→	var tbl2 lockTable
207→	if !grant(&tbl2, "f", a, max-5, 5, true) {
208→		t.Fatal("A 加锁应成功")
209→	}
210→	if grant(&tbl2, "f", b, max-10, 20, true) {
211→		t.Fatal("包含关系也是相交，B 必须被拒")
212→	}
213→}
214→
215→// TestLockAdjacentRangesDoNotConflict：相邻但不重叠的区间必须能同时持有。
216→// 这是"off by one"最容易翻车的地方。
217→func TestLockAdjacentRangesDoNotConflict(t *testing.T) {
218→	var tbl lockTable
219→	a, b := &Open{}, &Open{}
220→
221→	if !grant(&tbl, "f", a, 0, 100, true) {
222→		t.Fatal("A 锁 [0,100) 应成功")
223→	}
224→	if !grant(&tbl, "f", b, 100, 100, true) {
225→		t.Fatal("B 锁 [100,200) 与 [0,100) 相邻不相交，应成功")
226→	}
227→	if grant(&tbl, "f", b, 99, 1, true) {
228→		t.Fatal("[99,100) 落在 A 的区间内，应被拒")
229→	}
230→}
