232→// TestLockCommandsRegistered：LOCK / CHANGE_NOTIFY / OPLOCK_BREAK
233→// 都必须挂上分发表，否则会落到 defaultHandler 回 STATUS_NOT_SUPPORTED
234→// 而不是各自的语义；且它们都**必须**产生响应（不是 CANCEL 那种无响应命令）。
235→func TestLockCommandsRegistered(t *testing.T) {
236→	for _, c := range []wire.Command{
237→		wire.CommandLock, wire.CommandChangeNotify, wire.CommandOplockBreak,
238→	} {
239→		if !Registered(c) {
240→			t.Errorf("%s 未注册到分发表", c)
241→		}
242→		if NoResponse(c) {
243→			t.Errorf("%s 不应被标记为无响应命令", c)
244→		}
245→	}
246→}
