## 1. Verbatim Function: `fsctl_zero_data`

```c
static NTSTATUS fsctl_zero_data(TALLOC_CTX *mem_ctx,
				struct tevent_context *ev,
				struct files_struct *fsp,
				DATA_BLOB *in_input)
{
	struct file_zero_data_info zdata_info;
	enum ndr_err_code ndr_ret;
	struct lock_struct lck;
	int mode;
	uint64_t len;
	int ret;
	NTSTATUS status;

	if (fsp == NULL) {
		return NT_STATUS_FILE_CLOSED;
	}

	/* WRITE_DATA permission is required */
	status = check_any_access_fsp(fsp, FILE_WRITE_DATA);
	if (!NT_STATUS_IS_OK(status)) {
		return status;
	}

	/* allow regardless of whether FS supports sparse or not */

	ndr_ret = ndr_pull_struct_blob(in_input, mem_ctx, &zdata_info,
			(ndr_pull_flags_fn_t)ndr_pull_file_zero_data_info);
	if (ndr_ret != NDR_ERR_SUCCESS) {
		DBG_ERR("failed to unmarshall zero data request\n");
		return NT_STATUS_INVALID_PARAMETER;
	}

	if (zdata_info.beyond_final_zero < zdata_info.file_off) {
		DBG_ERR("invalid zero data params: off %" PRIu64
			", bfz, %" PRIu64 "\n",
			zdata_info.file_off,
			zdata_info.beyond_final_zero);
		return NT_STATUS_INVALID_PARAMETER;
	}

	/* convert strange "beyond final zero" param into length */
	len = zdata_info.beyond_final_zero - zdata_info.file_off;

	if (len == 0) {
		DBG_NOTICE("zero data called with zero length range\n");
		return NT_STATUS_OK;
	}

	init_strict_lock_struct(fsp,
				fsp->op->global->open_persistent_id,
				zdata_info.file_off,
				len,
				WRITE_LOCK,
				&lck);

	if (!SMB_VFS_STRICT_LOCK_CHECK(fsp->conn, fsp, &lck)) {
		DBG_NOTICE("failed to lock range for zero-data\n");
		return NT_STATUS_FILE_LOCK_CONFLICT;
	}

	/*
	 * MS-FSCC <58> Section 2.3.67
	 * This FSCTL sets the range of bytes to zero (0) without extending the
	 * file size.
	 *
	 * The VFS_FALLOCATE_FL_KEEP_SIZE flag is used to satisfy this
	 * constraint.
	 */

	mode = VFS_FALLOCATE_FL_PUNCH_HOLE | VFS_FALLOCATE_FL_KEEP_SIZE;
	ret = SMB_VFS_FALLOCATE(fsp, mode, zdata_info.file_off, len);
	if (ret == -1)  {
		status = map_nt_error_from_unix_common(errno);
		DBG_NOTICE("zero-data fallocate(0x%x) failed: %s\n",
			   mode,
			   strerror(errno));
		return status;
	}

	if (!fsp->fsp_flags.is_sparse && lp_strict_allocate(SNUM(fsp->conn))) {
		/*
		 * File marked non-sparse and "strict allocate" is enabled -
		 * allocate the range that we just punched out.
		 * In future FALLOC_FL_ZERO_RANGE could be used exclusively for
		 * this, but it's currently only supported on XFS and ext4.
		 *
		 * The newly allocated range still won't be found by SEEK_DATA
		 * for QAR, but stat.st_blocks will reflect it.
		 */
		ret = SMB_VFS_FALLOCATE(fsp, VFS_FALLOCATE_FL_KEEP_SIZE,
					zdata_info.file_off, len);
		if (ret == -1)  {
			status = map_nt_error_from_unix_common(errno);
			DBG_WARNING("fallocate failed: %s\n", strerror(errno));
			return status;
		}
	}

	return NT_STATUS_OK;
}
```

### `fsctl_zero_data` – NTSTATUS by branch
| Condition | Returned NTSTATUS |
|-----------|-------------------|
| `fsp == NULL` | `NT_STATUS_FILE_CLOSED` |
| `check_any_access_fsp` fails | status from that check (e.g. access denied) |
| NDR unmarshall fails | `NT_STATUS_INVALID_PARAMETER` |
| `beyond_final_zero < file_off` | `NT_STATUS_INVALID_PARAMETER` |
| `len == 0` | `NT_STATUS_OK` |
| Strict lock check fails | `NT_STATUS_FILE_LOCK_CONFLICT` |
| `SMB_VFS_FALLOCATE` (punch hole) fails | mapped Unix error (e.g. `NT_STATUS_*` from `errno`) |
| Strict allocate re‑alloc fails | mapped Unix error |
| Success | `NT_STATUS_OK` |

*Note: This function performs **no** `in_max_output` validation (it has no such parameter).*

---

## 2. Verbatim Function: `fsctl_qar` (FSCTL_QUERY_ALLOCATED_RANGES handler)

```c
static NTSTATUS fsctl_qar(TALLOC_CTX *mem_ctx,
			  struct tevent_context *ev,
			  struct files_struct *fsp,
			  DATA_BLOB *in_input,
			  size_t in_max_output,
			  DATA_BLOB *out_output)
{
	struct fsctl_query_alloced_ranges_req qar_req;
	struct fsctl_query_alloced_ranges_rsp qar_rsp;
	DATA_BLOB qar_array_blob = data_blob_null;
	uint64_t max_off;
	enum ndr_err_code ndr_ret;
	int ret;
	NTSTATUS status;
	SMB_STRUCT_STAT sbuf;

	if (fsp == NULL) {
		return NT_STATUS_FILE_CLOSED;
	}

	/* READ_DATA permission is required */
	status = check_any_access_fsp(fsp, FILE_READ_DATA);
	if (!NT_STATUS_IS_OK(status)) {
		return status;
	}

	ndr_ret = ndr_pull_struct_blob(in_input, mem_ctx, &qar_req,
		(ndr_pull_flags_fn_t)ndr_pull_fsctl_query_alloced_ranges_req);
	if (ndr_ret != NDR_ERR_SUCCESS) {
		DEBUG(0, ("failed to unmarshall QAR req\n"));
		return NT_STATUS_INVALID_PARAMETER;
	}

	/*
	 * XXX Windows Server 2008 & 2012 servers don't return lock-conflict
	 * for QAR requests over an exclusively locked range!
	 */

	ret = SMB_VFS_FSTAT(fsp, &sbuf);
	if (ret == -1) {
		status = map_nt_error_from_unix_common(errno);
		DEBUG(2, ("fstat failed: %s\n", strerror(errno)));
		return status;
	}

	if ((qar_req.buf.len == 0)
	 || (sbuf.st_ex_size == 0)
	 || (qar_req.buf.file_off >= sbuf.st_ex_size)) {
		/* zero length range or after EOF, no ranges to return */
		return NT_STATUS_OK;
	}

	/* check for integer overflow */
	if (qar_req.buf.file_off + qar_req.buf.len < qar_req.buf.file_off) {
		return NT_STATUS_INVALID_PARAMETER;
	}

	/* must have enough space for at least one range */
	if (in_max_output < sizeof(struct file_alloced_range_buf)) {
		DEBUG(2, ("QAR max %lu insufficient for one range\n",
			  (unsigned long)in_max_output));
		return NT_STATUS_BUFFER_TOO_SMALL;
	}

	/*
	 * Maximum offset is either the last valid offset _before_ EOF, or the
	 * last byte offset within the requested range. -1 converts length to
	 * offset, which is easier to work with for SEEK_DATA/SEEK_HOLE, E.g.:
	 *
	 * /off=0             /off=512K          /st_ex_size=1M
	 * |-------------------------------------|
	 * | File data                           |
	 * |-------------------------------------|
	 *                                                   QAR end\
	 *                    |=====================================|
	 *                    |    QAR off=512K, len=1M             |
	 *                    |=================^===================|
	 *                                   max_off=1M - 1
	 *             QAR end\
	 * |==================|
	 * |QAR off=0 len=512K|
	 * |==================|
	 *                   ^
	 *                max_off=512K - 1
	 */
	max_off = MIN(sbuf.st_ex_size,
		      qar_req.buf.file_off + qar_req.buf.len) - 1;

	if (!fsp->fsp_flags.is_sparse) {
		struct file_alloced_range_buf qar_buf;

		/* file is non-sparse, claim file_off->max_off is allocated */
		qar_buf.file_off = qar_req.buf.file_off;
		/* + 1 to convert maximum offset back to length */
		qar_buf.len = max_off - qar_req.buf.file_off + 1;

		status = fsctl_qar_buf_push(mem_ctx, &qar_buf, &qar_array_blob);
	} else {
		status = fsctl_qar_seek_fill(mem_ctx, fsp, qar_req.buf.file_off,
					     max_off, in_max_output,
					     &qar_array_blob);
	}

	if (NT_STATUS_IS_OK(status)
	 || NT_STATUS_EQUAL(status, STATUS_BUFFER_OVERFLOW)) {
		/* marshall response. STATUS_BUFFER_OVERFLOW=truncated */
		qar_rsp.far_buf_array = qar_array_blob;

		ndr_ret = ndr_push_struct_blob(out_output, mem_ctx, &qar_rsp,
		 (ndr_push_flags_fn_t)ndr_push_fsctl_query_alloced_ranges_rsp);
		if (ndr_ret != NDR_ERR_SUCCESS) {
			DEBUG(0, ("failed to marshall QAR rsp\n"));
			return NT_STATUS_INVALID_PARAMETER;
		}
	}

	return status;
}
```

### `fsctl_qar` – `in_max_output` validation
- **Check location:** after integer‑overflow check, before building ranges:
  ```c
  /* must have enough space for at least one range */
  if (in_max_output < sizeof(struct file_alloced_range_buf)) {
      DEBUG(2, ("QAR max %lu insufficient for one range\n",
                (unsigned long)in_max_output));
      return NT_STATUS_BUFFER_TOO_SMALL;
  }
  ```
- Additional `in_max_output` usage: passed to `fsctl_qar_seek_fill` (sparse case) which returns `STATUS_BUFFER_OVERFLOW` if a pushed range would exceed `in_max_output` (truncated response, not an error branch per se).

### `fsctl_qar` – NTSTATUS by branch
| Condition | Returned NTSTATUS |
|-----------|-------------------|
| `fsp == NULL` | `NT_STATUS_FILE_CLOSED` |
| `check_any_access_fsp` fails | status from check (e.g. access denied) |
| NDR unmarshall fails | `NT_STATUS_INVALID_PARAMETER` |
| `fstat` fails | mapped Unix error |
| `qar_req.buf.len == 0` **or** `st_ex_size == 0` **or** `file_off >= st_ex_size` | `NT_STATUS_OK` (empty list) |
| Integer overflow in `file_off + len` | `NT_STATUS_INVALID_PARAMETER` |
| `in_max_output < sizeof(struct file_alloced_range_buf)` | `NT_STATUS_BUFFER_TOO_SMALL` |
| `fsctl_qar_buf_push` / `ndr_push` fails | `NT_STATUS_INVALID_PARAMETER` (or `NT_STATUS_NO_MEMORY` inside `qar_seek_fill` returned as `NT_STATUS_NO_MEMORY` → propagated) |
| Sparse seek fill truncated | `STATUS_BUFFER_OVERFLOW` (still marshalled) |
| Success (non‑sparse or sparse full) | `NT_STATUS_OK` |

---

## 3. How an Empty Range List Is Returned

An empty allocated‑ranges list is produced **without** building any `file_alloced_range_buf` and **without** calling the marshalling of a populated array. Specifically, in `fsctl_qar`:

```c
	if ((qar_req.buf.len == 0)
	 || (sbuf.st_ex_size == 0)
	 || (qar_req.buf.file_off >= sbuf.st_ex_size)) {
		/* zero length range or after EOF, no ranges to return */
		return NT_STATUS_OK;
	}
```

- The function returns `NT_STATUS_OK` immediately.
- `out_output` is **not** modified (it remains the `data_blob_null` or caller‑initialized empty blob from `state->out_output` in the dispatch wrapper).
- Consequently, the response sent to the client contains **no range entries** (zero‑length array), and the status code indicates success.

This is the only path that yields an empty list; the non‑empty paths always push at least one range (or truncate with `STATUS_BUFFER_OVERFLOW`).

