## Verbatim Case Block: `FSCTL_GET_SHADOW_COPY_DATA`

```c
	case FSCTL_GET_SHADOW_COPY_DATA:
	{
		/*
		 * This is called to retrieve the number of Shadow Copies (a.k.a. snapshots)
		 * and return their volume names.  If max_data_count is 16, then it is just
		 * asking for the number of volumes and length of the combined names.
		 *
		 * pdata is the data allocated by our caller, but that uses
		 * total_data_count (which is 0 in our case) rather than max_data_count.
		 * Allocate the correct amount and return the pointer to let
		 * it be deallocated when we return.
		 */
		struct shadow_copy_data *shadow_data = NULL;
		bool labels = False;
		uint32_t labels_data_count = 0;
		uint32_t i;
		char *cur_pdata = NULL;

		if (max_out_len < 16) {
			DBG_ERR("FSCTL_GET_SHADOW_COPY_DATA: max_data_count(%u) < 16 is invalid!\n",
				max_out_len);
			return NT_STATUS_INVALID_PARAMETER;
		}

		if (max_out_len > 16) {
			labels = True;
		}

		shadow_data = talloc_zero(ctx, struct shadow_copy_data);
		if (shadow_data == NULL) {
			DBG_ERR("TALLOC_ZERO() failed!\n");
			return NT_STATUS_NO_MEMORY;
		}

		/*
		 * Call the VFS routine to actually do the work.
		 */
		if (SMB_VFS_GET_SHADOW_COPY_DATA(fsp, shadow_data, labels)!=0) {
			int log_lev = DBGLVL_ERR;
			if (errno == 0) {
				/* broken module didn't set errno on error */
				status = NT_STATUS_UNSUCCESSFUL;
			} else {
				status = map_nt_error_from_unix(errno);
				if (NT_STATUS_EQUAL(status,
						    NT_STATUS_NOT_SUPPORTED)) {
					log_lev = DBGLVL_INFO;
				}
			}
			DEBUG(log_lev, ("FSCTL_GET_SHADOW_COPY_DATA: "
					"connectpath %s, failed - %s.\n",
					fsp->conn->connectpath,
					nt_errstr(status)));
			TALLOC_FREE(shadow_data);
			return status;
		}

		labels_data_count = (shadow_data->num_volumes * 2 *
					sizeof(SHADOW_COPY_LABEL)) + 2;

		if (!labels) {
			*out_len = 16;
		} else {
			*out_len = 12 + labels_data_count;
		}

		if (max_out_len < *out_len) {
			DBG_ERR("FSCTL_GET_SHADOW_COPY_DATA: max_data_count(%u) too small (%u) bytes needed!\n",
				max_out_len, *out_len);
			TALLOC_FREE(shadow_data);
			return NT_STATUS_BUFFER_TOO_SMALL;
		}

		cur_pdata = talloc_zero_array(ctx, char, *out_len);
		if (cur_pdata == NULL) {
			TALLOC_FREE(shadow_data);
			return NT_STATUS_NO_MEMORY;
		}

		*out_data = cur_pdata;

		/* num_volumes 4 bytes */
		SIVAL(cur_pdata, 0, shadow_data->num_volumes);

		if (labels) {
			/* num_labels 4 bytes */
			SIVAL(cur_pdata, 4, shadow_data->num_volumes);
		}

		/* needed_data_count 4 bytes */
		SIVAL(cur_pdata, 8, labels_data_count);

		cur_pdata += 12;

		DBG_DEBUG("FSCTL_GET_SHADOW_COPY_DATA: %u volumes for path[%s].\n",
			  shadow_data->num_volumes, fsp_str_dbg(fsp));
		if (labels && shadow_data->labels) {
			for (i=0; i<shadow_data->num_volumes; i++) {
				size_t len = 0;
				status = srvstr_push(cur_pdata, req_flags,
					    cur_pdata, shadow_data->labels[i],
					    2 * sizeof(SHADOW_COPY_LABEL),
					    STR_UNICODE|STR_TERMINATE, &len);
				if (!NT_STATUS_IS_OK(status)) {
					TALLOC_FREE(*out_data);
					TALLOC_FREE(shadow_data);
					return status;
				}
				cur_pdata += 2 * sizeof(SHADOW_COPY_LABEL);
				DEBUGADD(DBGLVL_DEBUG,("Label[%u]: '%s'\n",i,shadow_data->labels[i]));
			}
		}

		TALLOC_FREE(shadow_data);

		return NT_STATUS_OK;
	}
```

---

## Specific Extracted Details

### 1. Threshold on `max_out_len` and NTSTATUS when too small
- **Initial validation:** If `max_out_len < 16`, returns `NT_STATUS_INVALID_PARAMETER` (this is a hard minimum, not the "too small for data" check).
- **Data fit validation:** After computing `*out_len`, the code checks:
  ```c
  if (max_out_len < *out_len) {
      ...
      return NT_STATUS_BUFFER_TOO_SMALL;
  }
  ```
  The exact threshold compared is `max_out_len < *out_len` (where `*out_len` is either 16 or `12 + labels_data_count`). The NTSTATUS returned when too small is **`NT_STATUS_BUFFER_TOO_SMALL`**.

### 2. Formula for `labels_data_count` (does it add +2?)
Yes, it adds +2:
```c
labels_data_count = (shadow_data->num_volumes * 2 * sizeof(SHADOW_COPY_LABEL)) + 2;
```
The `+ 2` is explicitly present in the expression.

### 3. Values assigned to `*out_len` when labels is false vs true
- **Labels false** (`max_out_len <= 16`, so only the count is requested):
  ```c
  *out_len = 16;
  ```
- **Labels true** (`max_out_len > 16`):
  ```c
  *out_len = 12 + labels_data_count;
  ```
  (where `labels_data_count` includes the `+2` from above).

### 4. Exact `SIVAL` offsets and what is written
The code writes three 4‑byte values via `SIVAL` (which stores a uint32 at the given offset):
- **Offset 0:** `SIVAL(cur_pdata, 0, shadow_data->num_volumes);`  
  → writes the number of volumes (`num_volumes`).
- **Offset 4:** `SIVAL(cur_pdata, 4, shadow_data->num_volumes);`  
  → writes the number of labels (`num_volumes` again), **but only if `labels` is true**. If labels is false, offset 4 is left as zero (from `talloc_zero_array`) and no `SIVAL` is executed for offset 4.
- **Offset 8:** `SIVAL(cur_pdata, 8, labels_data_count);`  
  → writes `labels_data_count` (the computed size needed for the label strings, including the `+2`).

After these writes, `cur_pdata` is advanced by 12 bytes (`cur_pdata += 12;`) before the label strings are appended.

