	//
	// SnapShotArraySize **包含**这 2 个字节，所以零快照时它是 2 而不是 0。
	// 规范原文没写清楚，这个值来自 Samba 的实际行为（见下方 ioctlEnumerateSnapshots
	// 的注释），它才是 smbclient 期望的对端。
	srvSnapshotArrayTerminator = 2
)

