// 实际行为为准（它是 smbclient 期望的对端）：
//
//  1. SnapShotArraySize 填 **2** 而不是 0。Samba：
//     `labels_data_count = (num_volumes * 2 * sizeof(SHADOW_COPY_LABEL)) + 2;`
//     这个 +2 是标签列表末尾的双 NUL 终止符，零快照时只剩下它。
//  2. MaxOutputResponse < 16 回 **STATUS_INVALID_PARAMETER**（不是
//     BUFFER_TOO_SMALL、也不是截断 + BUFFER_OVERFLOW）。Samba：
//     `if (max_out_len < 16) return NT_STATUS_INVALID_PARAMETER;`
//     BUFFER_TOO_SMALL 只用于"头部放得下但标签放不下"的第二道检查。
func ioctlEnumerateSnapshots(ctx *Context, req *wire.IoctlRequest) error {
	// 需要一个有效句柄：快照是按句柄所在的卷枚举的。
	open, err := ctx.resolveOpen(req.FileID)
	if err != nil {
		return err
	}
	if open.IsPipe() {
		return status.InvalidDeviceRequest
	}

	if req.MaxOutputResponse < srvSnapshotProbeSize {
		return status.InvalidParameter
	}
	// MaxOutputResponse == 16 是"只问数量"的探测，不带标签。
	labels := req.MaxOutputResponse > srvSnapshotProbeSize

	// 零快照：SnapShots 数组里只剩双 NUL 终止符。
	const numSnapshots = 0
	arraySize := uint32(numSnapshots*0 + srvSnapshotArrayTerminator)

	outLen := srvSnapshotProbeSize // 不带标签时固定回 16 字节（末尾 4 字节零填充）
	if labels {
		outLen = srvSnapshotHeaderSize + int(arraySize)
	}
	if uint32(outLen) > req.MaxOutputResponse {
		// 零快照时到不了这里（outLen ≤ 16 ≤ MaxOutputResponse），
		// 留着是为了将来真支持快照时不漏这道检查。
		return status.BufferTooSmall
	}

	out := make([]byte, outLen)
	binary.LittleEndian.PutUint32(out[0:4], numSnapshots) // NumberOfSnapShots
	if labels {
		// 不带标签时这个字段必须留 0（Samba 在 !labels 时根本不写它）。
		binary.LittleEndian.PutUint32(out[4:8], numSnapshots) // NumberOfSnapShotsReturned
	}
	binary.LittleEndian.PutUint32(out[8:12], arraySize) // SnapShotArraySize
	// out[12:] 保持全零：即那 2 字节双 NUL 终止符（或 16 字节形态下的零填充）。

	return appendIoctlResponse(ctx, req, out)
}

