// dataFile 取出句柄背后的 *os.File，顺带做关闭检查。
//
// 直接读 h.f 是有竞态的：Close 会在持锁的情况下把它置 nil。
func (h *localHandle) dataFile() (*os.File, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.closed {
		return nil, ErrClosed
	}
	if h.f == nil {
